    pub(crate) fn local(&self) -> Option<Output> {
        match self {
            Self::ConsistentColorHue { input } => Some(Output::ConsistentColorHue(
                waddle_xmpp_client_ffi::consistent_color_hue(input.clone()),
            )),
            Self::ParseJid { input } => Some(Output::ParseJid(waddle_xmpp_client_ffi::parse_jid(
                input.clone(),
            ))),
            _ => None,
        }
    }
